snippet_css:
:root{
  --bg: #FAF3E7;
  --fg: #43301F;
  --muted: #6B5544;
  --surface: #F1E3CC;
  --border: #D8C3A0;
  --accent: #A0522D;
  --accent-fg: #FFF7EC;
  --accent-grad: linear-gradient(180deg,#A8552E,#8E4726);
  --radius: 22px;
  --radius-sm: 14px;
  --shadow: 0 12px 26px rgba(74,52,38,.16);
  --btn-shadow: 0 4px 0 rgba(74,52,38,.20);
  --art-bg: linear-gradient(#E8D5B7,#D99058 58%,#A0522D);
  --media-bg: linear-gradient(#E8D5B7,#C2703D);
  --cta-bg: linear-gradient(180deg,#F4D58D,#E8D5B7);
  --input-bg: #FFFDF8;
  --ok: #4C5C40;
  --warn: #B4441F;
  --gold: #D4A017;
  --olive: #5E6F50;
  --font-script: 'Allura',cursive;
  --font-display: 'Fraunces','Noto Serif TC',serif;
  --font-body: 'Lora','Noto Serif TC',serif;
  --font-mono: 'Lora',ui-serif,serif;
  --focus-ring: var(--accent);
}

snippet_tailwind:
